<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Http\Requests\SaveVoucherRequest;use App\Models\ServiceType;use App\Models\Voucher;use App\Services\AuditLogger;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class VoucherController extends Controller
{public function index(Request $r):View{abort_unless($r->user()->can('vouchers.manage'),403);return view('admin.vouchers.index',['vouchers'=>Voucher::whereNull('mitra_id')->latest()->paginate(20)]);}public function create(Request $r):View{return view('admin.vouchers.form',['services'=>ServiceType::where('is_transactional',true)->get()]);}public function store(SaveVoucherRequest $r,AuditLogger $audit):RedirectResponse{$voucher=DB::transaction(function()use($r,$audit){$data=$r->safe()->except('service_type_ids');$data['code']=strtoupper($data['code']);$voucher=Voucher::create($data+['mitra_id'=>null,'created_by'=>$r->user()->id]);$voucher->serviceTypes()->sync($r->validated('service_type_ids'));$audit->record('voucher.platform_created',$voucher,[],$voucher->toArray(),$r->user());return $voucher;});return redirect()->route('admin.vouchers.index')->with('status','Voucher platform dibuat.');}public function status(Request $r,Voucher $voucher,AuditLogger $audit):RedirectResponse{abort_unless($r->user()->can('vouchers.manage')&&$voucher->mitra_id===null,403);$d=$r->validate(['status'=>'required|in:active,paused,archived']);$before=$voucher->status->value;$voucher->update(['status'=>$d['status']]);$audit->record('voucher.status_updated',$voucher,['status'=>$before],$d,$r->user());return back();}}
